58	  public async getTags(
59	    searchText: string,
60	    page: number,
61	    emptyQueryFilter?: boolean
62	  ) {
63	    const encodedValue = getEncodedFqn(escapeESReservedCharacters(searchText));
64	
65	    // Build the queryFilter by merging disabled:false with any existing filters
66	    const disabledFilter = getTermQuery({ disabled: 'false' });
67	
68	    let mergedQueryFilter = {};
69	    if (emptyQueryFilter) {
70	      // If emptyQueryFilter is true, only use the disabled filter
71	      mergedQueryFilter = disabledFilter;
72	    } else {
73	      const hasClassificationFilter = !isEmpty(
74	        queryFilterToRemoveSomeClassification
75	      );
76	      if (hasClassificationFilter) {
77	        // Merge both filters: disabled:false (must) + classification exclusions (must_not)
78	        mergedQueryFilter = {
79	          query: {
80	            bool: {
81	              must: disabledFilter.query.bool.must,
82	              must_not:
83	                queryFilterToRemoveSomeClassification.query.bool.must_not,
84	            },
85	          },
86	        };
87	      } else {
88	        mergedQueryFilter = disabledFilter;
89	      }
90	    }
91	
92	    const res = await searchQuery({
93	      query: `*${encodedValue}*`,
94	      pageNumber: page,
95	      pageSize: PAGE_SIZE,
96	      queryFilter: mergedQueryFilter,
97	      searchIndex: SearchIndex.TAG,
98	    });
99	
100	    return {
101	      data: res.hits.hits.map(({ _source }) => ({
102	        label: _source.fullyQualifiedName ?? '',
103	        value: _source.fullyQualifiedName ?? '',
104	        data: _source,
105	      })),
106	      paging: {
107	        total: res.hits.total.value,
108	      },
109	    };
110	  }
